# -*- coding: utf-8 -*-
"""
Cotizador visual: paquetes de seleccion rapida, conceptos libres y aviso de
"grupo excluyente".

- Paquetes: al cotizar aparecen como botones; un toque agrega todos sus
  accesorios (con sus fotos). Se pueden marcar "ya viene seleccionado al
  abrir el equipo". El descuento del paquete ahora es opcional (puede ser 0%).
- Boton "+ Concepto libre" al cotizar: renglones libres (envio, paqueteria,
  instalacion...) con nombre y precio que suman al total y salen en la
  cotizacion.
- "Grupo" de accesorio renombrado a "Grupo excluyente" con explicacion y
  avisos: si dos accesorios comparten grupo, al elegir uno se quita el otro
  (ahora se avisa en pantalla por que se quito).

Requiere fix_cotizador_visual.py y fix_cotizador_visual_colores.py ya aplicados.
Toca: frontend/index.html. Se puede correr varias veces.

Uso: en la carpeta del repo:
    py -3 fix_cotizador_visual_paquetes_libres.py
"""
import os
import sys

ARCHIVOS = {'frontend/index.html': [['    .cv-layout > * { min-width:0; }\n', '    .cv-layout > * { min-width:0; }\n    .cv-paq { padding:6px 10px; font-size:12px; text-transform:none; letter-spacing:0; }\n    .cv-paq.on { border-color:var(--copper); box-shadow:inset 0 0 0 1px var(--copper); }\n    .cv-mas { padding:4px 10px; font-size:12px; text-transform:none; letter-spacing:0; margin:2px 0 4px; }\n    .cv-aviso { font-size:12px; color:var(--alta); margin:4px 0 8px; }\n'], ["  CV_SEL = { activos: [], desc: {}, precio: {}, fuente: {}, color: CV_BASE, cliente: { nombre: '', telefono: '', tipo: 'publico' } };\n", "  CV_SEL = { activos: [], desc: {}, precio: {}, fuente: {}, color: CV_BASE, libres: [], aviso: '', cliente: { nombre: '', telefono: '', tipo: 'publico' } };\n  (cfg.combos || []).filter(cb => cb.por_defecto).forEach(cb => cv_aplicarPaquete(cb));\n"], ['function cv_combosAplicados() {\n  return (CV_KIT.config.combos || []).filter(cb =>\n    Number(cb.descuento_pct) > 0 && (cb.requiere || []).length &&\n    cb.requiere.every(u => CV_SEL.activos.includes(u)));\n}\n', 'function cv_combosAplicados() {\n  return (CV_KIT.config.combos || []).filter(cb =>\n    Number(cb.descuento_pct) > 0 && (cb.requiere || []).length &&\n    cb.requiere.every(u => CV_SEL.activos.includes(u)));\n}\n\n// ---------- Paquetes (selección rápida) ----------\n\nfunction cv_grupoDe(uid) {\n  const a = CV_KIT.config.accesorios.find(x => x.uid === uid);\n  return ((a && a.grupo) || \'\').trim().toLowerCase();\n}\n\nfunction cv_nombreAcc(uid) {\n  const a = CV_KIT.config.accesorios.find(x => x.uid === uid);\n  return (a && a.nombre) || \'\';\n}\n\nfunction cv_paqueteCompleto(cb) {\n  const req = (cb.requiere || []).filter(u => CV_KIT.config.accesorios.some(a => a.uid === u));\n  return req.length > 0 && req.every(u => CV_SEL.activos.includes(u));\n}\n\n// Agrega todos los accesorios del paquete (y quita los que choquen por\n// "grupo" con alguno de ellos). Solo cambia el estado, no redibuja.\nfunction cv_aplicarPaquete(cb) {\n  const req = (cb.requiere || []).filter(u => CV_KIT.config.accesorios.some(a => a.uid === u));\n  const grupos = req.map(cv_grupoDe).filter(Boolean);\n  const quitados = CV_SEL.activos.filter(u => !req.includes(u) && grupos.includes(cv_grupoDe(u)));\n  CV_SEL.activos = CV_SEL.activos.filter(u => !quitados.includes(u));\n  req.forEach(u => { if (!CV_SEL.activos.includes(u)) CV_SEL.activos.push(u); });\n  return quitados;\n}\n\nfunction cv_togglePaquete(i) {\n  const cb = (CV_KIT.config.combos || [])[i];\n  if (!cb) return;\n  CV_SEL.aviso = \'\';\n  if (cv_paqueteCompleto(cb)) {\n    CV_SEL.activos = CV_SEL.activos.filter(u => !cb.requiere.includes(u));\n  } else {\n    const quitados = cv_aplicarPaquete(cb);\n    if (quitados.length) CV_SEL.aviso = `Se quitó ${quitados.map(u => `"${cv_nombreAcc(u)}"`).join(\', \')} porque es del mismo grupo que un accesorio del paquete (solo se elige uno).`;\n  }\n  cv_renderCotizar();\n}\n\nfunction cv_htmlPaquetes(cfg) {\n  const paquetes = (cfg.combos || []).map((cb, i) => ({ cb, i }))\n    .filter(x => (x.cb.requiere || []).some(u => cfg.accesorios.some(a => a.uid === u)));\n  if (!paquetes.length) return \'\';\n  return `\n    <span class="cv-etq">Paquetes — toca para agregar todo junto</span>\n    <div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:6px;">\n      ${paquetes.map(({ cb, i }) => {\n        const on = cv_paqueteCompleto(cb);\n        return `<button type="button" class="secondary cv-paq${on ? \' on\' : \'\'}" onclick="cv_togglePaquete(${i})">${on ? \'✅\' : \'📦\'} ${escapeHtml(cb.nombre || \'Paquete\')}${Number(cb.descuento_pct) > 0 ? ` <span style="opacity:.8;">(−${cb.descuento_pct}%)</span>` : \'\'}</button>`;\n      }).join(\'\')}\n    </div>`;\n}\n\n// ---------- Conceptos libres (envío, paquetería, instalación…) ----------\n\nfunction cv_agregarLibre() {\n  CV_SEL.libres.push({ uid: \'L\' + cv_uid(), nombre: \'\', precio: 0 });\n  cv_renderCotizar();\n  const n = document.getElementById(`cv_libre_nom_${CV_SEL.libres[CV_SEL.libres.length - 1].uid}`);\n  if (n) n.focus();\n}\n\nfunction cv_setLibre(uid, campo, valor) {\n  const l = CV_SEL.libres.find(x => x.uid === uid);\n  if (!l) return;\n  l[campo] = campo === \'precio\' ? (parseFloat(valor) || 0) : valor;\n  cv_actualizarTotales();\n}\n\nfunction cv_quitarLibre(uid) {\n  CV_SEL.libres = CV_SEL.libres.filter(x => x.uid !== uid);\n  cv_renderCotizar();\n}\n\nfunction cv_htmlLibres() {\n  return `\n    <datalist id="cv_sugerencias_libres">\n      <option value="Envío"></option><option value="Paquetería"></option><option value="Flete"></option>\n      <option value="Instalación"></option><option value="Capacitación"></option>\n    </datalist>\n    ${CV_SEL.libres.length ? \'<span class="cv-etq">Conceptos adicionales</span>\' : \'\'}\n    ${CV_SEL.libres.map(l => `\n      <div class="cv-acc on" style="cursor:default; gap:6px;">\n        <input id="cv_libre_nom_${l.uid}" list="cv_sugerencias_libres" value="${escapeHtml(l.nombre)}" placeholder="Concepto (ej. Envío)" style="flex:1; min-width:0;"\n               oninput="cv_setLibre(\'${l.uid}\',\'nombre\',this.value)" />\n        <span style="font-size:13px; color:var(--muted);">$</span>\n        <input type="number" min="0" step="0.01" value="${Number(l.precio) || \'\'}" placeholder="0.00" style="width:110px; flex:none;"\n               oninput="cv_setLibre(\'${l.uid}\',\'precio\',this.value)" />\n        <button type="button" class="secondary" style="padding:4px 8px; flex:none; color:var(--copper); border-color:var(--copper);" title="Quitar" onclick="cv_quitarLibre(\'${l.uid}\')">✕</button>\n      </div>`).join(\'\')}\n    <button type="button" class="secondary cv-mas" title="Agregar un concepto libre (envío, paquetería, instalación…)" onclick="cv_agregarLibre()">＋ Concepto libre</button>`;\n}\n'], ['    return { uid, p, precio, desc, combos: misCombos, descEfectivo, neto: precio * (1 - descEfectivo / 100) };\n  }).filter(Boolean);\n}\n', "    return { uid, p, precio, desc, combos: misCombos, descEfectivo, neto: precio * (1 - descEfectivo / 100) };\n  }).filter(Boolean).concat((CV_SEL.libres || []).map(l => {\n    const precio = Math.max(0, Number(l.precio) || 0);\n    return { uid: l.uid, p: { nombre: (l.nombre || '').trim() }, precio, desc: 0, combos: [], descEfectivo: 0, neto: precio, libre: true };\n  }));\n}\n"], ["    const a = cfg.accesorios.find(x => x.uid === uid);\n    const grupo = ((a && a.grupo) || '').trim().toLowerCase();\n    if (grupo) {\n      CV_SEL.activos = CV_SEL.activos.filter(u => {\n        const o = cfg.accesorios.find(x => x.uid === u);\n        return !(o && (o.grupo || '').trim().toLowerCase() === grupo);\n      });\n    }\n    CV_SEL.activos.push(uid);\n  }\n  cv_renderCotizar();\n", '    const a = cfg.accesorios.find(x => x.uid === uid);\n    const grupo = ((a && a.grupo) || \'\').trim().toLowerCase();\n    CV_SEL.aviso = \'\';\n    if (grupo) {\n      const quitados = CV_SEL.activos.filter(u => cv_grupoDe(u) === grupo);\n      CV_SEL.activos = CV_SEL.activos.filter(u => !quitados.includes(u));\n      if (quitados.length) {\n        CV_SEL.aviso = `Se quitó ${quitados.map(u => `"${cv_nombreAcc(u)}"`).join(\', \')} porque es del mismo grupo "${a.grupo.trim()}" que "${a.nombre}" (de ese grupo solo se elige uno). Si deben poder ir juntos, borra el grupo en Editar equipo.`;\n      }\n    }\n    CV_SEL.activos.push(uid);\n  }\n  cv_renderCotizar();\n'], ['        ${cfg.accesorios.length ? `<span class="cv-etq">Accesorios — toca para agregar o quitar</span>` : \'\'}\n', '        ${cv_htmlPaquetes(cfg)}\n        ${cfg.accesorios.length ? `<span class="cv-etq">Accesorios — toca para agregar o quitar</span>` : \'\'}\n        ${CV_SEL.aviso ? `<div class="cv-aviso">⚠️ ${escapeHtml(CV_SEL.aviso)}</div>` : \'\'}\n'], ['\n        <div class="cv-caja" style="margin-top:12px;">\n          <div style="display:flex; justify-content:space-between; font-size:13px;"><span>Precio de lista</span><span id="cv_tot_lista"></span></div>\n', '        ${cv_htmlLibres()}\n\n        <div class="cv-caja" style="margin-top:12px;">\n          <div style="display:flex; justify-content:space-between; font-size:13px;"><span>Precio de lista</span><span id="cv_tot_lista"></span></div>\n'], ["  if (!nombre) { alert('Captura el nombre del cliente.'); document.getElementById('cv_cliente_nombre').focus(); return; }\n  await conBloqueoDeBoton(boton, async () => {", "  if (!nombre) { alert('Captura el nombre del cliente.'); document.getElementById('cv_cliente_nombre').focus(); return; }\n  if ((CV_SEL.libres || []).some(l => !(l.nombre || '').trim() && Number(l.precio) > 0)) {\n    alert('Hay un concepto libre con precio pero sin nombre — escríbele qué es (ej. Envío) o quítalo.');\n    return;\n  }\n  await conBloqueoDeBoton(boton, async () => {"], ['        items: t.lineas.map(l => ({', '        items: t.lineas.filter(l => !l.libre || l.p.nombre).map(l => ({'], ['      ${key !== CV_BASE ? `<div class="field"><label>Grupo (opcional)</label>\n        <input value="${escapeHtml(p.grupo || \'\')}" placeholder="ej. monitor" oninput="cv_setProd(\'${key}\',\'grupo\',this.value)" />\n        <div style="font-size:11px; color:var(--muted); margin-top:3px;">Accesorios con el mismo grupo: solo se puede elegir uno.</div>\n      </div>` : \'<div></div>\'}', '      ${key !== CV_BASE ? `<div class="field"><label>Grupo excluyente (opcional)</label>\n        <input value="${escapeHtml(p.grupo || \'\')}" placeholder="déjalo vacío normalmente" oninput="cv_setProd(\'${key}\',\'grupo\',this.value)" />\n        <div style="font-size:11px; color:var(--muted); margin-top:3px;">Solo para accesorios que se REEMPLAZAN entre sí (ej. "monitor" en el de 22" y en el de 27"): de un mismo grupo solo se puede elegir uno. Para venderlos juntos NO uses esto — usa los Paquetes (paso 4).</div>\n        ${cv_htmlAvisoGrupo(key)}\n      </div>` : \'<div></div>\'}'], ["function cv_agregarCombo() {\n  CV_EDIT.config.combos.push({ uid: cv_uid(), nombre: '', descuento_pct: 5, incluye_base: true, requiere: [] });\n  cv_renderEditor();\n}\n", 'function cv_agregarCombo() {\n  CV_EDIT.config.combos.push({ uid: cv_uid(), nombre: \'\', descuento_pct: 0, incluye_base: true, por_defecto: false, requiere: [] });\n  cv_renderEditor();\n}\n\nfunction cv_htmlAvisoGrupo(key) {\n  const p = cv_prod(key);\n  const g = ((p && p.grupo) || \'\').trim().toLowerCase();\n  if (!g) return \'\';\n  const otros = CV_EDIT.config.accesorios.filter(a => a.uid !== key && (a.grupo || \'\').trim().toLowerCase() === g);\n  if (!otros.length) return \'\';\n  return `<div style="font-size:11px; color:var(--alta); margin-top:3px;">⚠️ No se podrá elegir junto con: ${otros.map(a => escapeHtml(a.nombre || \'(sin nombre)\')).join(\', \')}</div>`;\n}\n\nfunction cv_htmlAvisoComboGrupo(cb) {\n  const accs = CV_EDIT.config.accesorios.filter(a => cb.requiere.includes(a.uid) && (a.grupo || \'\').trim());\n  const vistos = {};\n  const choques = [];\n  accs.forEach(a => {\n    const g = a.grupo.trim().toLowerCase();\n    if (vistos[g]) choques.push(`${vistos[g]} y ${a.nombre}`); else vistos[g] = a.nombre;\n  });\n  return choques.length ? `<div style="font-size:11px; color:var(--alta); margin-bottom:8px;">⚠️ ${escapeHtml(choques.join(\'; \'))} tienen el mismo grupo excluyente — no pueden ir juntos en un paquete. Borra el grupo en esos accesorios.</div>` : \'\';\n}\n'], ["  c.combos = (c.combos || []).map(cb => ({ nombre: '', descuento_pct: 0, incluye_base: true, requiere: [], ...cb }));\n", "  c.combos = (c.combos || []).map(cb => ({ uid: cv_uid(), nombre: '', descuento_pct: 0, incluye_base: true, por_defecto: false, requiere: [], ...cb }));\n"], ['    <span class="cv-etq">4 · Descuentos por paquete (opcional)</span>\n    <p style="font-size:12px; color:var(--muted); margin:0 0 8px;">Se aplican solos cuando el vendedor elige TODOS los accesorios marcados — encima del descuento de cada producto.</p>', '    <span class="cv-etq">4 · Paquetes (opcional)</span>\n    <p style="font-size:12px; color:var(--muted); margin:0 0 8px;">Un paquete agrupa accesorios: al cotizar aparece como botón y con un toque se agregan todos (con sus fotos). Puedes marcarlo para que ya venga seleccionado al abrir el equipo. Si le pones descuento, se aplica solo cuando están TODOS sus accesorios — encima del descuento de cada producto.</p>'], ['        <div style="font-size:12px; margin-bottom:6px;">Aplica cuando se eligen todos estos accesorios:</div>', '        <div style="font-size:12px; margin-bottom:6px;">Accesorios que incluye el paquete:</div>'], ['            <input type="checkbox" class="cv-check" ${cb.requiere.includes(a.uid) ? \'checked\' : \'\'} onchange="cv_toggleComboReq(${i}, \'${a.uid}\', this.checked)" /> ${escapeHtml(a.nombre || \'(sin nombre)\')}</label>`).join(\'\') || \'<span style="font-size:12px; color:var(--muted);">Primero agrega accesorios.</span>\'}\n        </div>\n        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">\n          <label style="text-transform:none; font-weight:400; font-size:12px; display:flex; gap:5px; align-items:center;">\n            <input type="checkbox" class="cv-check" ${cb.incluye_base !== false ? \'checked\' : \'\'} onchange="CV_EDIT.config.combos[${i}].incluye_base=this.checked" /> El descuento también aplica al producto principal</label>', '            <input type="checkbox" class="cv-check" ${cb.requiere.includes(a.uid) ? \'checked\' : \'\'} onchange="cv_toggleComboReq(${i}, \'${a.uid}\', this.checked); cv_renderEditor();" /> ${escapeHtml(a.nombre || \'(sin nombre)\')}</label>`).join(\'\') || \'<span style="font-size:12px; color:var(--muted);">Primero agrega accesorios.</span>\'}\n        </div>\n        ${cv_htmlAvisoComboGrupo(cb)}\n        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">\n          <div style="display:flex; flex-direction:column; gap:4px;">\n          <label style="text-transform:none; font-weight:400; font-size:12px; display:flex; gap:5px; align-items:center;">\n            <input type="checkbox" class="cv-check" ${cb.por_defecto ? \'checked\' : \'\'} onchange="CV_EDIT.config.combos[${i}].por_defecto=this.checked" /> Ya viene seleccionado al abrir el equipo</label>\n          <label style="text-transform:none; font-weight:400; font-size:12px; display:flex; gap:5px; align-items:center;">\n            <input type="checkbox" class="cv-check" ${cb.incluye_base !== false ? \'checked\' : \'\'} onchange="CV_EDIT.config.combos[${i}].incluye_base=this.checked" /> El descuento también aplica al producto principal</label>\n          </div>'], ['    <button type="button" class="secondary" onclick="cv_agregarCombo()">+ Agregar descuento por paquete</button>', '    <button type="button" class="secondary" onclick="cv_agregarCombo()">+ Agregar paquete</button>']]}

def main():
    errores = []
    cambios = {}
    for ruta, pares in ARCHIVOS.items():
        if not os.path.exists(ruta):
            errores.append(f"No encontre {ruta} -- corre el script desde la carpeta del repo.")
            continue
        with open(ruta, encoding="utf-8", newline="") as f:
            original = f.read()
        texto = original
        for i, (viejo, nuevo) in enumerate(pares, 1):
            # En Windows git puede dejar los archivos con saltos de linea
            # CRLF (\r\n): se prueba el texto tal cual y, si no aparece,
            # la version con CRLF.
            variantes = [(viejo, nuevo)]
            if "\n" in viejo:
                variantes.append((viejo.replace("\n", "\r\n"), nuevo.replace("\n", "\r\n")))
            if any(nv in texto for _, nv in variantes):
                continue  # ya aplicado
            elegido = None
            for vj, nv in variantes:
                if texto.count(vj) == 1:
                    elegido = (vj, nv)
                    break
            if not elegido:
                n = max(texto.count(vj) for vj, _ in variantes)
                errores.append(f"{ruta}: cambio #{i} -- el texto a reemplazar aparece {n} veces (se esperaba 1).")
                continue
            texto = texto.replace(elegido[0], elegido[1], 1)
        if texto != original:
            cambios[ruta] = texto
    if errores:
        print("NO se aplico nada:")
        for e in errores:
            print("  -", e)
        sys.exit(1)
    for ruta, texto in cambios.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("Actualizado:", ruta)
    if not cambios:
        print("Todo ya estaba aplicado, no hubo cambios.")
    else:
        print("Listo.")


if __name__ == "__main__":
    main()
